   T('For the first record, return Pass if Energy_J meets or exceeds its two-way requirement, otherwise Hold.',rows[0][3]>=get(rows[0])?'Pass':'Hold','=IF(Data!D2>=INDEX(Matrix!B2:C5,MATCH(Data!B2,Matrix!A2:A5,0),MATCH(Data!C2,Matrix!B1:C1,0)),"Pass","Hold")',['IF','INDEX','MATCH'],hints('Use the requirement for the same grade and orientation.','Wrap the two-way result in an IF comparison.','=IF(Data!D2>=INDEX(____),"Pass","Hold")')),
   T('Return the difference between the first grade’s LPA and TWA requirements: LPA minus TWA.',s[0].rows[0][1]-s[0].rows[0][2],'=INDEX(Matrix!B2:C5,1,1)-INDEX(Matrix!B2:C5,1,2)',['INDEX'],hints('Both requirements belong to grade G1.','Subtract the second matrix column from the first.','=INDEX(____,1,1)-INDEX(____,1,2)'))
